const recomputeJobInputsAtTime = `-- name: RecomputeJobInputsAtTime :exec
UPDATE ledger_jobs j SET inputs_at_time = COALESCE((
    SELECT SUM(m.quantity * m.unit_at_time) FROM ledger_job_materials m
    WHERE m.owner_kind = j.owner_kind AND m.owner_id = j.owner_id AND m.job_id = j.job_id), 0)
WHERE j.owner_kind = $1 AND j.owner_id = $2 AND j.job_id = $3
`

type RecomputeJobInputsAtTimeParams struct {
	OwnerKind string `json:"owner_kind"`
	OwnerID   int64  `json:"owner_id"`
	JobID     int64  `json:"job_id"`
}

func (q *Queries) RecomputeJobInputsAtTime(ctx context.Context, arg RecomputeJobInputsAtTimeParams) error {
	_, err := q.db.ExecContext(ctx, recomputeJobInputsAtTime, arg.OwnerKind, arg.OwnerID, arg.JobID)
	return err
}

